×「構台の支柱は施工性を優先し、本設柱の位置に合わせて設ける」→誤り。干渉を避ける
×「構台の高さは地下1階の梁下と同一とする」→誤り。30cm程度の余裕をみる
○「構台の幅員は、車両がすれ違う場合6〜8m程度とする」
○「覆工板は跳ね上がり防止措置を施す」

