        body: `▼ゼロから：全部調べるか、一部で判断するか
100本の鉄筋のうち何本かを引っ張って切ってしまえば、その鉄筋はもう使えません。全部調べたら製品が残らない検査もあります。また、ボルト100万本を全部調べる時間も費用もありません。そこで一部を抜き取って全体を判断する抜取検査が使われます。ただし一部からの推定である以上、必ず誤りの可能性が残ります。この構造を理解することが検査計画の出発点です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 全数検査と抜取検査の使い分け
━━━━━━━━━━━━━━━━━━━━━━
・全数検査が必要な場合：不良品が一つでも混入すると重大な結果を招く（人命・重要構造部）、不良率が高い、検査が簡単で費用が安い、ロットの大きさが小さい
・抜取検査が適する場合：破壊検査である、検査項目が多く全数では費用と時間がかかる、ある程度の不良の混入が許される、ロットが大きく生産が連続している
・無試験検査・間接検査：品質保証が確実な供給者から購入する場合に、書類（試験成績書）で代える
・抜取検査の前提：ロットが均一であること、サンプルがランダムに選ばれること、合格判定の基準が明確であること
★破壊検査は必ず抜取検査。全数では製品が残らない

【図解】検査方式の選択
　条件｜適する検査｜理由
　破壊検査である｜抜取検査｜全数では製品がなくなる
　不良が致命的である｜全数検査｜一つの見逃しが重大
　ロットが大きく連続生産｜抜取検査｜費用と時間の制約
　供給者の品質が保証済み｜間接検査｜試験成績書で代替
　⇒ 「壊すなら抜取」「致命的なら全数」で判断する
　⚠ 不良率が高いロットに抜取検査を適用すると、合格しても不良が多数残る

━━━━━━━━━━━━━━━━━━━━━━
🔑 抜取検査に伴う二つの誤り
━━━━━━━━━━━━━━━━━━━━━━
・生産者危険（第一種の誤り）：本来合格すべき良いロットが不合格になる確率。記号はアルファで、一般に5パーセント程度に設定
・消費者危険（第二種の誤り）：本来不合格とすべき悪いロットが合格してしまう確率。記号はベータで、一般に10パーセント程度に設定
・合格品質水準（AQL）：合格させたいロットの不良率の上限
・ロット許容不良率（LTPD）：これ以上悪ければ不合格としたい不良率
⚠ 生産者危険は「良いものを落とす」、消費者危険は「悪いものを通す」。取り違えが頻出

━━━━━━━━━━━━━━━━━━━━━━
🔑 OC曲線（検査特性曲線）の読み方
━━━━━━━━━━━━━━━━━━━━━━
・横軸にロットの不良率、縦軸にそのロットが合格する確率をとった曲線
・不良率が上がるほど合格確率は下がる、右下がりの曲線になる
・サンプルの大きさnを大きくすると、曲線は急峻になり、良いロットと悪いロットを識別する力が上がる
・合格判定個数cを小さくすると、曲線は全体に左下へ寄り、検査が厳しくなる
・nとcを同じ比率で増やしても厳しさは変わらない。識別力はnの大きさで決まる
→ 「識別力を上げたいならサンプルを増やす」「厳しくしたいなら合格判定個数を減らす」

【図解】サンプル数と判定個数の効果
　操作｜OC曲線の変化｜結果
　nを大きくする｜曲線が急になる｜良否の識別力が向上
　cを小さくする｜曲線が左へ寄る｜検査が厳しくなる
　cを大きくする｜曲線が右へ寄る｜検査が甘くなる
　nを小さくする｜曲線が緩やかになる｜識別力が低下
　⇒ 縦の切れ味＝n、左右の位置＝c
　⚠ ロットの大きさNを変えても、OC曲線はほとんど変わらない

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：抜取検査の方式
━━━━━━━━━━━━━━━━━━━━━━
・計数規準型抜取検査：不適合品の個数で判定する。生産者危険と消費者危険の両方を指定して設計する
・計量規準型抜取検査：特性値の平均や標準偏差で判定する。同じ精度ならサンプル数を少なくできる
・1回抜取検査：1回のサンプルで合否を決める。手続きが単純
・2回抜取検査・多回抜取検査：1回目で判定できないときに追加サンプルを取る。平均のサンプル数を減らせる
・調整型抜取検査（なみ検査・きつい検査・ゆるい検査）：供給者の品質実績に応じて検査の厳しさを切り替える
・建設資材では、JISの製品規格に基づく試験成績書の確認（間接検査）と、現場での抜取確認を組み合わせるのが一般的
→ 「同じ精度ならサンプルが少ないのは計量型」「実績がよければ検査を緩められる」の二点を押さえる

━━━━━━━━━━━━━━━━━━━━━━
⚠ 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
×「生産者危険とは、不良ロットが合格してしまう確率である」→誤り。それは消費者危険
×「サンプルの大きさを大きくするとOC曲線は緩やかになる」→誤り。急峻になる
×「破壊検査は全数検査で行うのが原則である」→誤り。抜取検査による
○「合格判定個数を小さくすると検査は厳しくなる」
○「抜取検査はロットが均一であることを前提とする」

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★破壊検査・大ロット・多項目＝抜取検査
★致命的欠陥・高不良率・小ロット＝全数検査
★生産者危険＝良品ロットを落とす（アルファ、約5パーセント）
★消費者危険＝不良ロットを通す（ベータ、約10パーセント）
★nを増やすと識別力向上、cを減らすと厳格化`,
