━━━━━━━━━━━━━━━━━━━━━━
×「管理値は規格値と同じ値に設定するのが合理的である」→誤り。内側に設定する
×「QC工程表は元請の内部資料であり、協力会社に示す必要はない」→誤り。作業者へ展開する
×「隠ぺいされる部分の検査は、仕上げ完了後に抜取で行う」→誤り。隠ぺい前に行う
○「QC工程表には管理項目・管理値・確認方法・確認者・記録様式を記載する」
○「立会検査はあらかじめ日程を通知して実施する」

