・色むら：同一面には同一ロットの材料を用いる。ロットが変わる場合は目地や見切りで区切る
・接着系の仕上げは、下地の含水率・清掃状態・プライマーの塗布量が結果を左右する。着手前の下地検査を必ず行う
・仕上げ材の養生：完成後の傷は手直しが難しい。養生材の種類と撤去時期を工程表に明記する
