        body: `▼ゼロから：事故が起きる前に危険を点数化する
これまでの安全対策は「事故が起きた→対策する」の繰り返しでした。リスクアセスメントは、事故が起きる前に危険性を洗い出し、点数を付けて、危ないものから順に対策する手法です。すべての危険を同時にゼロにはできないので、優先順位を付けるという発想が要になります。労働安全衛生法では、建設業の事業者に実施の努力義務が課されています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 リスクアセスメントの手順
━━━━━━━━━━━━━━━━━━━━━━
・手順1　危険性又は有害性の特定：作業を細かく分解し、どこにどんな危険が潜むかを洗い出す
・手順2　リスクの見積り：「重篤度（けがの重さ）」と「発生の可能性」などを点数化して掛けるか足す
・手順3　リスク低減措置の内容の検討：優先順位の高い順に対策を考える
・手順4　リスク低減措置の実施：計画に組み込み、実行する
・手順5　結果の記録と見直し：残留リスクを記録し、作業者に周知する
・実施時期：工事の計画段階、作業手順を定めるとき、新しい機械や工法を導入するとき、災害が発生したとき
★危険の「特定」から始まる。いきなり対策を考えるのは誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 リスクの見積り方
━━━━━━━━━━━━━━━━━━━━━━
・要素は一般に三つ：重篤度（致命的・重大・中程度・軽度）、発生可能性（極めて高い・比較的高い・可能性がある・ほとんどない）、暴露頻度（作業に触れる頻度）
・加算法：各要素の点数を足す。掛算法：各要素の点数を掛ける
・合計点をリスクレベル（4段階から5段階）に区分し、レベルごとに「直ちに中止」「速やかに措置」「計画的に措置」「必要に応じ措置」を決める
・重篤度の評価は「実際に起きたけが」ではなく「起こりうる最悪のけが」で行う
⚠ 発生頻度が低くても、重篤度が致命的なら高リスクになる。掛算でも足し算でも、この性質が保たれるように配点する

【図解】リスクの見積り例（加算法）
　評価要素｜区分と点数｜今回の評価
　重篤度｜致命的10・重大6・中程度3・軽微1｜墜落のため致命的（10点）
　可能性｜高い6・中4・低2・ほぼなし1｜手すり未設置のため高い（6点）
　暴露頻度｜頻繁4・時々2・まれ1｜毎日作業のため頻繁（4点）
　合計｜10＋6＋4｜20点
　⇒ 合計20点はリスクレベル4（許容できない）
　⇒ 直ちに作業を中止し、手すりを設置してから再開する
　⚠ 「点数が高い＝先に対策する」が原則。人手や予算を理由に順序を変えない

━━━━━━━━━━━━━━━━━━━━━━
🔑 リスク低減措置の優先順位
━━━━━━━━━━━━━━━━━━━━━━
・第1　本質的対策：危険な作業そのものをなくす。高所作業を地上での先組みに変える、危険な材料を代替する
・第2　工学的対策：設備で防ぐ。手すり・囲い・覆い・安全装置・インターロック
・第3　管理的対策：手順・教育・立入禁止・監視人・作業時間の制限
・第4　個人用保護具：墜落制止用器具、保護帽、保護めがね
・保護具は最後の手段。保護具に頼る対策だけで済ませるのは不適切
→ 「なくす→囲う→決める→着ける」の順。上位ほど人の注意力に依存しない

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：作業手順書とリスクアセスメントの連動
━━━━━━━━━━━━━━━━━━━━━━
・作業手順書には、手順ごとに「予想される危険」と「安全のポイント」を並記する。これがリスクアセスメントの成果物になる
・手順の分解は、一つの動作で一つの手順とする。粗すぎると危険が見えず、細かすぎると使われない
・危険源の分類：墜落、転倒、はさまれ・巻き込まれ、飛来・落下、崩壊、感電、火災、有害物、熱中症
・リスクの再評価は、工法・機械・人員・季節が変わったときに行う。同じ現場でも条件が変われば点数は変わる
・手順書は職長が作り、元請が確認し、作業員全員に説明する。読み上げるだけでなく、現場で実地に確認する
・手順どおりに作業できない状況が生じたら、その場で作業を止め、手順を見直してから再開する
→ リスクアセスメントの結果が作業手順書に載って初めて、現場の行動が変わる

━━━━━━━━━━━━━━━━━━━━━━
⚠ 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
×「リスク低減措置は、まず保護具の着用を徹底することから検討する」→誤り。最後の手段
×「リスクの見積りにおける重篤度は、過去に実際に発生した災害の程度で評価する」→誤り。起こりうる最悪で評価
×「リスクアセスメントは災害が発生した後に実施するものである」→誤り。計画段階から実施
○「リスク低減措置の検討は、本質的対策、工学的対策、管理的対策、保護具の順とする」
○「低減措置後に残るリスク（残留リスク）は記録し、作業者に周知する」

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★手順＝特定→見積り→措置の検討→実施→記録
★見積りは重篤度・可能性・頻度
★重篤度は「起こりうる最悪」で評価
★低減の順序＝本質的→工学的→管理的→保護具
★残留リスクは記録して周知`,
