○「安全施工サイクルには日常・週間・月間の活動がある」

×「KY活動は元請の担当者が危険を指摘し、作業員に守らせる活動である」→誤り。全員参加で出し合う
○「4S活動による通路の確保は、転倒災害と飛来落下災害の防止に直結する」
