崩れれば人が埋まる、外れれば人が落ちる——そういう作業には、その場で指揮を執る有資格者を置かなければなりません。それが作業主任者です。免許または技能講習という資格が必要で、作業のたびに氏名と職務を掲示します。どの作業に必要か、そして数値の基準（高さ・深さ・重さ）を覚えることが試験対策の中心になります。

━━━━━━━━━━━━━━━━━━━━━━
