━━━━━━━━━━━━━━━━━━━━━━
・地山の掘削作業主任者：掘削面の高さが2m以上の地山の掘削
・土止め支保工作業主任者：土止め支保工の切りばり又は腹起こしの取付け又は取外し
・型枠支保工の組立て等作業主任者：型枠支保工の組立て又は解体
・足場の組立て等作業主任者：つり足場、張出し足場、または高さが5m以上の構造の足場の組立て・解体・変更
・建築物等の鉄骨の組立て等作業主任者：高さが5m以上の金属製の部材により構成される建築物の骨組みの組立て・解体・変更
・コンクリート造の工作物の解体等作業主任者：高さが5m以上のコンクリート造の工作物の解体又は破壊
・木造建築物の組立て等作業主任者：軒の高さが5m以上の木造建築物の構造部材の組立て等
・酸素欠乏危険作業主任者、有機溶剤作業主任者、石綿作業主任者、鉛作業主任者、特定化学物質作業主任者
★「5m以上」が並ぶのが特徴。地山の掘削だけが2m以上

【図解】高さの基準で覚える作業主任者
　作業｜基準｜資格の区分
　地山の掘削｜掘削面の高さ2m以上｜技能講習
　足場の組立て等｜高さ5m以上・つり足場・張出し足場｜技能講習
　鉄骨の組立て等｜高さ5m以上の金属製骨組み｜技能講習
　コンクリート造工作物の解体等｜高さ5m以上｜技能講習
