・組立て・解体の途中こそ最も墜落の危険が高いという事実に対応した工法
・方式：手すり先送り方式、手すり据置き方式、手すり先行専用足場方式
・併せて、足場の最上層および外側に「働きやすい安全な足場」の考え方（幅広の床、二段手すり、幅木）を適用する
・厚生労働省のガイドラインで推奨されており、公共工事では標準的に採用される

