クレーンの災害は、吊り荷の落下、クレーンの転倒、荷や機体との接触、そして架空電線への接触です。どれも一瞬で重大災害になります。防ぐ方法は決まっていて、能力の範囲で使う、地盤を固める、合図を統一する、そして吊り荷の下に人を立ち入らせない。この四つを数値と手順で押さえます。

