━━━━━━━━━━━━━━━━━━━━━━
・つり上げ荷重：構造上および材料に応じて負荷させることができる最大の荷重。フック等のつり具の質量を含む
・定格荷重：つり上げ荷重から、フック・グラブバケット等のつり具の質量を差し引いた荷重。作業半径やジブの長さによって変わる
・定格総荷重：定格荷重につり具の質量を加えたもの
・作業半径が大きくなるほど定格荷重は小さくなる。最大作業半径での能力で判断する
・移動式クレーンは、その定格荷重を超えて使用してはならない
