        id: 'sk-ka-n51', title: '実行予算の作成と原価管理の手順', emoji: '💴',
        body: `▼ゼロから：契約金額と、実際にかかるお金は別物
工事を受注すると請負金額が決まります。しかしそれは「もらえる金額」であって、「使ってよい金額」ではありません。使ってよい金額を自分たちで積み上げて決めたものが実行予算です。実行予算より安く造れば利益が出て、超えれば赤字になります。原価管理とは、この実行予算と実際の支出を突き合わせ、ずれを早く見つけて手を打つ活動です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 実行予算の性格
━━━━━━━━━━━━━━━━━━━━━━
・実行予算：現場が実際に施工するために必要な原価を、工種別・費目別に積み上げた予算
・請負金額（契約金額）より低く設定し、その差が予定利益となる
・見積書（積算）は受注のための金額、実行予算は施工のための金額。両者は目的が違うため、内訳も一致しない
・作成時期：着工前、施工計画が固まった段階。工法・数量・単価・協力会社が決まって初めて精度が出る
・工事の進行に伴って条件が変われば、実行予算も改訂する（予算の見直し）
★「実行予算は請負金額より低く設定する」は原則。同額や上回る設定は誤り

━━━━━━━━━━━━━━━━━━━━━━
🔑 工事原価の構成
━━━━━━━━━━━━━━━━━━━━━━
・材料費：主要資材、仮設材料の損料
・労務費：直接工事に従事する作業員の賃金
・外注費：専門工事会社への請負代金。建築工事では原価の大半を占めることが多い
・経費（直接経費）：機械経費、電力水道料、仮設費、運搬費、産業廃棄物処理費など
・現場管理費（間接費）：現場職員の給料、事務所経費、労災保険料、安全衛生費。工期に比例して増える
・一般管理費：本社の経費。現場の実行予算には通常含めず、本社で管理する
・工事原価＝直接工事費＋現場管理費（共通仮設費を含む）
⚠ 「変動費」と「固定費」の区分では、材料費・労務費・外注費が変動費、現場管理費が固定費に近い性格を持つ

【図解】実行予算の作成手順
　手順｜行うこと｜留意点
　1 数量の把握｜設計図書から数量を拾う｜見積時の数量を鵜呑みにしない
　2 施工計画の確定｜工法・機械・工期を決める｜工法が変われば原価が変わる
　3 単価の決定｜協力会社から見積を徴し比較｜複数社の相見積りを原則とする
　4 積上げと調整｜工種別に集計し目標利益と照合｜不足なら工法や手配を見直す
　⇒ 「数量→工法→単価→集計」の順。単価から入ると精度が出ない
　⚠ 実行予算の作成前に協力会社と契約すると、価格交渉の余地を失う

━━━━━━━━━━━━━━━━━━━━━━
🔑 原価管理のサイクル
━━━━━━━━━━━━━━━━━━━━━━
・手順1　実行予算を工種別・月別に配分する（原価の計画）
・手順2　毎月、実際に発生した原価（実績原価）を集計する
・手順3　同じ時点の出来高（完成した工事の価値）と対比する
・手順4　差異を分析する。数量差異（使いすぎ）と単価差異（高く買った）に分ける
・手順5　差異の原因を除去する処置をとり、残りの工事の予算を見直す
・手順6　結果を次の工事の見積・実行予算にフィードバックする
・原価は発生してから分かるのでは遅い。発注段階・手配段階で予測し、事前に手を打つ（原価の事前管理）
→ 「出来高と原価を必ず同じ時点で比べる」ことが差異分析の前提

━━━━━━━━━━━━━━━━━━━━━━
🔑 出来高と原価の対比
━━━━━━━━━━━━━━━━━━━━━━
・出来高（施工出来高）＞実績原価：利益が出ている状態
・出来高＜実績原価：原価が先行している。材料の先行手配や手直しの発生を疑う
・原価が先行する要因：材料の前倒し購入、仮設の過大投資、手直し工事、機械の遊休
・出来高が遅れる要因：工程の遅延、承認待ち、天候不良
・月次で「出来高・原価・差益」を並べ、累計と当月の両方を見る
・EVMのCV（EV−AC）は、まさにこの出来高と原価の対比を金額で表したもの

━━━━━━━━━━━━━━━━━━━━━━
🔑 深掘り：原価の発生時期と支払管理
━━━━━━━━━━━━━━━━━━━━━━
・原価は「発注したとき」に実質的に確定し、「支払ったとき」に現金が出る。管理は発注段階で行うのが最も効く
・発注管理表を作り、工種ごとに実行予算・見積額・発注額・出来高・支払済額を並べて管理する
・追加工事や設計変更は、指示を受けた時点で書面を残し、金額の合意を得てから着手する。口頭の指示のまま進めると回収できない
・協力会社への支払条件（締日・支払日・支払方法）は契約時に明確にする。下請代金支払遅延等防止の観点からも重要
・資金繰り：出来高払いの入金より、材料費と労務費の支払いが先行することが多い。月別の資金繰り表を作る
・予備費（コンティンジェンシー）を実行予算に一定割合見込み、予期しない事態に備える
→ 原価は「使ってから数える」のではなく「使う前に決める」もの

━━━━━━━━━━━━━━━━━━━━━━
⚠ 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
×「実行予算は請負金額と同額に設定する」→誤り。低く設定して利益を確保する
×「実行予算は受注前の見積書をそのまま用いてよい」→誤り。施工計画に基づき作り直す
×「原価管理は工事完了後に実績を集計して行う」→誤り。工事中に差異を把握し処置する
○「原価差異は数量差異と単価差異に分けて分析する」
○「実績原価と出来高は同じ時点で対比する」

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★実行予算＜請負金額。差が予定利益
★作成手順＝数量→工法→単価→集計
★原価管理＝計画→実績集計→出来高と対比→差異分析→処置
★差異は数量差異と単価差異に分解
★原価は事前管理（発注・手配の段階）が本命`,
