━━━━━━━━━━━━━━━━━━━━━━
×「特定建設作業実施届出書は都道府県知事に提出する」→誤り。市町村長へ
×「届出は作業開始の14日前までに行う」→誤り。7日前まで
×「騒音の規制基準は敷地境界において75デシベル以下」→誤り。85デシベル（75は振動）
×「圧入式くい打機を使用する作業は騒音規制法の特定建設作業に該当する」→誤り。除外される
○「特定建設作業は連続して6日を超えて行ってはならない」

